"use client";

import Link from "next/link";
import { LAB } from "@/lib/lab-data";
import {
  ChartNote, FlowTape, Meter, Panel, PanelHead, SectionHead, SeverityTag,
  VerdictChip, num, pct, unit,
} from "@/components/ui/kit";
import { cn } from "@/lib/utils";

const H = LAB.hero;
const U = unit(H.unit);

/* Landing sections. Every figure comes from LAB, which is generated by
 * web/scripts/export_lab_data.py from one call to src/pipeline.py::screen().
 * There is no hand-typed metric on this page - regenerate the dataset and the
 * copy follows it. */

function Wrap({
  id, children, tone = "card",
}: { id?: string; children: React.ReactNode; tone?: "card" | "panel" }) {
  return (
    <section
      id={id}
      className={cn(
        "border-b border-lab-rule",
        tone === "panel" ? "bg-lab-panel" : "bg-lab-card"
      )}
    >
      <div className="mx-auto max-w-[1400px] px-4 py-12 sm:px-6">{children}</div>
    </section>
  );
}

/* =====================================================================
 * §4  THE LIMITS CAN MISS THE RISK
 * ===================================================================== */

/** The one visual the whole project rests on: a limit, a part just under it,
 *  and the lot the part is supposed to resemble sitting far below. */
function LimitVsLot() {
  const w = 620, h = 340;
  const pl = 76, pr = 26, pt = 26, pb = 34;
  const x0 = pl, x1 = w - pr, y0 = pt, y1 = h - pb;
  const lo = 0, hi = 55;
  const Y = (v: number) => y1 - ((v - lo) / (hi - lo)) * (y1 - y0);

  const bins = LAB.hero.lotHist as readonly { x: number; n: number }[];
  const defects = LAB.hero.lotDefectHist as readonly { x: number; n: number }[];
  const peak = Math.max(...bins.map((b) => b.n), 1);
  const bh = (y1 - y0) / bins.length;
  // density grows to the right from the axis; sqrt compression so the
  // lognormal tail stays visible against one very tall central bin
  const wOf = (n: number) => Math.pow(n / peak, 0.62) * (x1 - x0) * 0.52;

  const yUsl = Y(H.usl);
  const yPart = Y(H.value168);
  const yMed = Y(H.lotMedian168);

  return (
    <svg viewBox={`0 0 ${w} ${h}`} className="w-full" role="img"
      aria-label="Datasheet limit against the lot population">
      <title>The component sits under the datasheet limit but far outside its lot</title>
      <defs>
        <pattern id="gp-lv" width="10" height="10" patternUnits="userSpaceOnUse">
          <path d="M10 0H0V10" fill="none" stroke="#0F1317" strokeOpacity="0.05" strokeWidth="1" />
        </pattern>
        <marker id="arw" markerWidth="7" markerHeight="7" refX="3.5" refY="3.5" orient="auto">
          <path d="M0,0 L7,3.5 L0,7 Z" fill="#A81E12" />
        </marker>
      </defs>

      <rect x={x0} y={y0} width={x1 - x0} height={y1 - y0} fill="#FCFCFB" />
      <rect x={x0} y={y0} width={x1 - x0} height={y1 - y0} fill="url(#gp-lv)" />

      {/* the lot's own dynamic band: median +/- 3 and 6 robust sigma */}
      {[3, 6].map((k) => {
        const top = Y(H.lotMedian168 + k * H.lotSigma168);
        return (
          <g key={k}>
            <line x1={x0} x2={x1} y1={top} y2={top} stroke="#12508C"
              strokeOpacity="0.45" strokeWidth="1" strokeDasharray="2 3" />
            <text x={x1 - 3} y={top - 3} textAnchor="end" className="font-mono"
              style={{ fontSize: 8, fill: "#12508C", fillOpacity: 0.8 }}>
              lot +{k}σ
            </text>
          </g>
        );
      })}

      {/* lot population, drawn as a density from the axis */}
      {bins.map((b, i) =>
        b.n ? (
          <rect key={`p${i}`} x={x0} y={y1 - (i + 1) * bh + 0.4}
            width={wOf(b.n)} height={Math.max(0.8, bh - 0.8)}
            fill="#12508C" fillOpacity="0.3" />
        ) : null
      )}
      {defects.map((b, i) =>
        b.n ? (
          <rect key={`d${i}`} x={x0} y={y1 - (i + 1) * bh + 0.4}
            width={wOf(b.n)} height={Math.max(0.8, bh - 0.8)}
            fill="#A81E12" fillOpacity="0.75" />
        ) : null
      )}

      {/* lot median */}
      <line x1={x0} x2={x1} y1={yMed} y2={yMed} stroke="#0F1317" strokeWidth="1.25" />
      <text x={x0 + 6} y={yMed - 5} className="font-mono"
        style={{ fontSize: 9, fill: "#0F1317", fontWeight: 700 }}>
        LOT MEDIAN {H.lotMedian168} {U}
      </text>

      {/* datasheet limit */}
      <line x1={x0} x2={x1} y1={yUsl} y2={yUsl} stroke="#A81E12" strokeWidth="2" />
      <text x={x0 + 6} y={yUsl - 6} className="font-mono"
        style={{ fontSize: 10, fill: "#A81E12", fontWeight: 700, letterSpacing: "0.06em" }}>
        DATASHEET LIMIT {H.usl} {U}
      </text>

      {/* the component */}
      <circle cx={x0 + (x1 - x0) * 0.62} cy={yPart} r="6.5" fill="#A81E12" />
      <circle cx={x0 + (x1 - x0) * 0.62} cy={yPart} r="11" fill="none"
        stroke="#A81E12" strokeWidth="1.1" strokeOpacity="0.45" />
      <text x={x0 + (x1 - x0) * 0.62 + 16} y={yPart + 4} className="font-mono"
        style={{ fontSize: 11, fill: "#A81E12", fontWeight: 700 }}>
        {H.value168} {U}
      </text>
      <text x={x0 + (x1 - x0) * 0.62 + 16} y={yPart + 16} className="font-mono"
        style={{ fontSize: 8, fill: "#59616D" }}>
        {H.serial} · passes by {H.marginLeft} {U}
      </text>

      {/* the argument: an arrow from the part down to where its lot lives */}
      <line
        x1={x0 + (x1 - x0) * 0.62} x2={x0 + (x1 - x0) * 0.62}
        y1={yPart + 13} y2={yMed - 8}
        stroke="#A81E12" strokeWidth="1.2" strokeDasharray="3 3" markerEnd="url(#arw)"
      />
      <text x={x0 + (x1 - x0) * 0.62 - 10} y={(yPart + yMed) / 2} textAnchor="end"
        className="font-mono" style={{ fontSize: 9, fill: "#A81E12", fontWeight: 700 }}>
        {H.driftZ}σ
      </text>
      <text x={x0 + (x1 - x0) * 0.62 - 10} y={(yPart + yMed) / 2 + 11} textAnchor="end"
        className="font-mono" style={{ fontSize: 8, fill: "#59616D" }}>
        abnormal vs its lot
      </text>

      {/* value axis */}
      {[0, 10, 20, 30, 40, 50].map((v) => (
        <g key={v}>
          <line x1={x0 - 4} x2={x0} y1={Y(v)} y2={Y(v)} stroke="#9CA2AB" />
          <text x={x0 - 7} y={Y(v) + 3} textAnchor="end" className="font-mono"
            style={{ fontSize: 8.5, fill: "#8C939E" }}>
            {v}
          </text>
        </g>
      ))}
      <text x={18} y={(y0 + y1) / 2} textAnchor="middle" className="font-mono"
        transform={`rotate(-90 18 ${(y0 + y1) / 2})`}
        style={{ fontSize: 8.5, fill: "#8C939E", letterSpacing: "0.12em" }}>
        {H.param} AT 168 h ({U})
      </text>
      <text x={(x0 + x1) / 2} y={h - 4} textAnchor="middle" className="font-mono"
        style={{ fontSize: 8, fill: "#8C939E", letterSpacing: "0.1em" }}>
        LOT {H.lot} POPULATION DENSITY · n={H.lotN} · RED = LABELLED LATENT DEFECTS
      </text>
      <rect x={x0} y={y0} width={x1 - x0} height={y1 - y0} fill="none" stroke="#9CA2AB" />
    </svg>
  );
}

